import json,random,statistics
from pathlib import Path
p=Path(__file__).parent
raw=json.loads((p/'same-launch-in_f64_dynamic_ansitrue-paired-mixed-loader-32/runs.json').read_text())
report={}
for mode in ['normal','loader']:
 runs=[r for r in raw['runs'] if r['address_mode']==mode]
 pairs=sorted({r['pair'] for r in runs})
 assert len(pairs)==16
 ratios=[]
 for pair in pairs:
  rows={r['label']:r for r in runs if r['pair']==pair}
  ratios.append(100*(rows['after']['median_ms']/rows['before']['median_ms']-1))
 medians={v:statistics.median(r['median_ms'] for r in runs if r['label']==v) for v in ['before','after']}
 rng=random.Random(88)
 bootstrap=sorted(statistics.median(rng.choices(ratios,k=len(ratios))) for _ in range(10000))
 report[mode]={'pairs':pairs,'paired_changes_pct':ratios,'median_ms':medians,'latency_change_pct':100*(medians['after']/medians['before']-1),'median_paired_change_pct':statistics.median(ratios),'paired_median_bootstrap_95_percentile_interval':[bootstrap[249],bootstrap[9749]]}
(p/'address-comparison.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report,indent=2))
